{
  "facts": [
    {
      "evidence": [2, 3, 9, 11, 13, 15],
      "text": "The After Scenario Questionnaire (ASQ) is a post-task questionnaire consisting of three statements: 'I am satisfied with the ease of completing the tasks in this scenario'; 'I am satisfied with the amount of time it took to complete the tasks in this scenario'; and 'I am satisfied with the support information that is comprised of online help, messages, documentation when completing the tasks'."
    },
    {
      "evidence": [4, 7],
      "text": "In the After Scenario Questionnaire (ASQ), users rate each statement on a seven-point rating scale in which rating 1 means strongly disagree with the statement and rating 7 means strongly agree with the statement."
    },
    {
      "evidence": [9, 11, 13, 16, 17, 18],
      "text": "The three statements of the After Scenario Questionnaire (ASQ) can be roughly mapped to the three usability measures in the International Organization for Standardization (ISO) definition: ease of completing the tasks relates to effectiveness, the amount of time taken to complete the tasks relates to efficiency, and the three statements together represent satisfaction."
    },
    {
      "evidence": [20],
      "text": "Feedback from the After Scenario Questionnaire (ASQ) can be summarised by taking either the average rating for each statement across all users who participated in the evaluation or the average rating for all statements taken together."
    }
  ]
}

{
  "facts": [
    {
      "evidence": [9, 11, 15, 17, 21, 22],
      "text": "The design of the Majuli virtual reality (VR) tour was framed by its broader objectives of capturing tangible and intangible heritage, enhancing user presence, and minimizing cyber sickness, with corresponding design considerations of user experience design, exploration of the island, and handling cyber sickness."
    },
