{
  "facts": [
    {
      "evidence": [1, 3, 4, 5, 6, 38],
      "text": "The Wizard of Oz approach is a prototype-creation technique in which a human subject believes they are interacting with an autonomous computer, but an unseen human operator, called the wizard, operates the computer and returns the requested response or result to the subject."
    },
